{
  "aic": "",
  "active": false,
  "lastModifiedTime": "2026-10-17T11:04:16+08:00",
  "protocolVersion": "02.02",
  "name": "互联验证回声智能体",
  "description": "双智能体互联早期验证的只读回声服务。取得平台分配的 AIC 和正式客户端证书后，通过平台 AMQPS Inbox 接收受控协调者的群组邀请。仅处理 operation 为 read-only-probe 且包含随机 nonce 的任务，将同一 nonce、自己的真实 AIC、观测时间、result=probe-received 和 business_mutations=0 作为 JSON 返回，等待协调者确认完成。仅接收本次验证指定身份、群组、会话与任务；不执行故障修复、文件操作或其他业务修改。当前等待平台审核与身份签发，未声明已经上线。",
  "version": "0.1.0",
  "provider": {},
  "securitySchemes": {
    "mtls": {
      "type": "mutualTLS",
      "description": "使用平台认可的 AIC clientAuth 证书通过 AMQPS EXTERNAL 认证接收 Inbox 邀请并参与 AIP 群组。"
    }
  },
  "endPoints": [
    {
      "url": "amqps://wt.ioa.pub:5671/acps?inbox=inbox_{AIC}",
      "transport": "AMQP",
      "security": [
        {
          "mtls": []
        }
      ]
    }
  ],
  "capabilities": {
    "streaming": false,
    "notification": false,
    "messageQueue": [
      "amqp:0.9.1"
    ]
  },
  "defaultInputModes": [
    "application/json",
    "text/plain"
  ],
  "defaultOutputModes": [
    "application/json"
  ],
  "skills": [
    {
      "id": "interop.probe.echo",
      "name": "只读随机值回声",
      "description": "接收文本承载的 JSON 任务 {operation: read-only-probe, nonce: 随机值}，回传同一随机值、真实 Partner AIC 和零业务修改标记。按 accepted、working、awaiting-completion、completed 状态流转，仅限受控双智能体验证。",
      "version": "0.1.0",
      "tags": [
        "互联验证",
        "AIP",
        "AMQPS Inbox",
        "只读",
        "nonce"
      ],
      "examples": [
        "{\"operation\":\"read-only-probe\",\"nonce\":\"测试时生成的随机值\"}"
      ],
      "inputModes": [
        "application/json",
        "text/plain"
      ],
      "outputModes": [
        "application/json"
      ]
    }
  ]
}
